#ifdef TEST_KIN16_DV
static void
test_kin16_dv (void)
{
  printf ("\n=== Group: kin16_dv (Zone Electrophoresis; vs C reference) ===\n");
  // Was: ten checks against magic constants carrying 15+ significant digits,
  // no provenance, landed in the same commit that changed the compiler -- a
  // regression lock that could detect change but never wrongness, and it read
  // only 5 of the 13 Edit fields at a single input.  kin16_ref.h now recomputes
  // the whole thing from the algorithm; every field of both Edit records is
  // compared, over several problem sizes.  (The reference agrees with those old
  // constants, so they were right -- but that is now a derived fact, not an
  // assumption.)
  // NSEG >= 2 throughout, deliberately.  OUT divides SUM2M/SUM1M with
  // SUM1M = (NSEG-1)*GZERO, so NSEG <= 1 makes that 0/0 and every statistic
  // comes back NaN.  NSEG = 1 is meaningless anyway (no zone to average over);
  // it is excluded as a bad input rather than guarded against.
  struct
  {
    int it, n, nseg;
  } cases[] = { { 2, 10, 5 }, { 1, 10, 5 }, { 5, 16, 7 }, { 3, 12, 3 },
                { 8, 20, 11 } };
  int compared = 0;
  bool all_ok = true, moved = false;
  for (auto c : cases)
    {
      kin16ref::Edit wa, wb;
      kin16ref::ref_kin16 (c.it, c.n, c.nseg, wa, wb);
      struct FUNC_MAIN_results r = func_MAIN (c.it, c.n, c.nseg);
      const double *g0 = (const double *)&r.res_0;
      const double *g1 = (const double *)&r.res_1;
      const double *w0 = (const double *)&wa;
      const double *w1 = (const double *)&wb;
      bool ok = true;
      for (int f = 0; f < 13; f++)
        {
          // relative, because the fields span 1e-7 to 1e0
          const double s0 = std::max (1e-300, fabs (w0[f]));
          const double s1 = std::max (1e-300, fabs (w1[f]));
          if (fabs (g0[f] - w0[f]) > 1e-9 * s0) ok = false;
          if (fabs (g1[f] - w1[f]) > 1e-9 * s1) ok = false;
          compared += 2;
        }
      // the state must actually evolve, or "matches" would be vacuous
      if (fabs (wb.YMEANM - wa.YMEANM) > 1e-12) moved = true;
      char msg[128];
      snprintf (msg, sizeof msg,
                "IT=%d N=%d NSEG=%d: all 13 Edit fields match the C reference, "
                "at T=0 and T=%g",
                c.it, c.n, c.nseg, c.it * 0.5);
      check (msg, ok);
      all_ok = all_ok && ok;
    }
  char msg[128];
  snprintf (msg, sizeof msg, "%d field comparisons against the reference",
            compared);
  check (msg, all_ok && compared == 130);
  check ("the concentration profile actually evolves (the match is not vacuous)",
         moved);
}
#endif

#ifdef TEST_CFFT_DV
struct FUNC_MAIN_results {
  sisal_array_t res_0;
  sisal_array_t res_1;
};
extern "C" struct FUNC_MAIN_results func_MAIN(int32_t LOG2N);

static void
test_cfft_dv (void)
{
  printf ("\n=== Group: cfft_dv (Cray-2 FFT) ===\n");
  // Reference: naive DFT in this FFT's convention (initsfft builds
  // wr = cos, wi = +sin, so X[k] = sum_j x[j] * e^{+2*pi*i*j*k/n}); the
  // Cray FFT leaves the spectrum in scrambled (digit-reversed) order, so
  // the check is permutation-invariant: every DFT bin must appear exactly
  // once in the output (greedy matching).
  // NB the previous hardcoded expected values were snapshots of a compiler
  // bug (let-multi-bind duplicated wr into wi, so the sin table was the
  // cos table); see multibind_dv.
  for (int lg = 2; lg <= 4; lg++) {
    int n = 1 << lg;
    struct FUNC_MAIN_results r = func_MAIN(lg);
    char nm[80];
    sprintf(nm, "cfft(%d) output sizes == %d", lg, n);
    check (nm, (int)r.res_0.size == n && (int)r.res_1.size == n);

    float *gr = (float*)r.res_0.data, *gi = (float*)r.res_1.data;
    bool *used = (bool*)calloc(n, sizeof(bool));
    int unmatched = 0;
    for (int k = 0; k < n; k++) {
      double Xr = 0, Xi = 0;
      for (int j = 0; j < n; j++) {
        double th = 2.0*M_PI*j*k/n;
        Xr += j*cos(th); Xi += j*sin(th);
      }
      double m = fmax(1.0, fmax(fabs(Xr), fabs(Xi)));
      int hit = -1;
      for (int t = 0; t < n && hit < 0; t++)
        if (!used[t] && fabs(gr[t]-Xr) < 5e-3*m && fabs(gi[t]-Xi) < 5e-3*m) hit = t;
      if (hit >= 0) used[hit] = true; else unmatched++;
    }
    sprintf(nm, "cfft(%d) output is a permutation of the DFT spectrum", lg);
    check (nm, unmatched == 0);
    free(used);
    if (r.res_0.data) free(r.res_0.data);
    if (r.res_1.data) free(r.res_1.data);
  }
}
#endif

#ifdef TEST_HILBERT_DV
extern "C" double func_MAIN(sisal_array_t HILBERT, sisal_array_t B);

static void
test_hilbert_dv (void)
{
  printf ("\n=== Group: hilbert_dv (LU residual; vs C reference solve) ===\n");
  // Was: one check, `resid < 1e-12`, at n = 4 only.  That bar is arbitrary --
  // it holds at n = 4 and fails at n = 8 purely from the Hilbert condition
  // number, not from any compiler fault -- and the rcond = 0 branch (-999) was
  // never reached.  Now the bar comes from an independent LU solve on the same
  // data, and both branches are covered.
  auto mk_mat = [] (const std::vector<double> &v, int n) {
    sisal_array_t a
        = sisal_array_alloc_sized (2, 4, (uint64_t)n * n, sizeof (double));
    a.dims[0] = n; a.dims[1] = n;
    a.lower_bound[0] = 1; a.lower_bound[1] = 1;
    memcpy (a.data, v.data (), v.size () * sizeof (double));
    return a;
  };
  auto mk_vec = [] (const std::vector<double> &v) {
    sisal_array_t a = sisal_array_alloc_empty (1, 4, v.size ());
    a.lower_bound[0] = 1;
    memcpy (a.data, v.data (), v.size () * sizeof (double));
    return a;
  };

  bool hil_ok = true, exact_ok = true;
  for (int n = 3; n <= 7; n++)
    {
      std::vector<double> H ((size_t)n * n), b ((size_t)n, 1.0);
      for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++) H[i * n + j] = 1.0 / (double)(i + j + 1);
      const double want = hilbref::ref_resid (n, H, b);
      sisal_array_t A = mk_mat (H, n), B = mk_vec (b);
      const double got = func_MAIN (A, B);
      // the reference says what is achievable here; allow a generous factor
      // plus an absolute floor, since both residuals are near zero
      if (!(got >= 0.0 && got <= 1e3 * want + 1e-10)) hil_ok = false;
      free (A.data); free (B.data);
    }
  check ("Hilbert n=3..7: the residual is no worse than an independent LU "
         "solve achieves on the same system",
         hil_ok);

  // A well-conditioned system with a KNOWN exact solution: conditioning is no
  // longer an excuse, so the residual must be at machine level.
  for (int n = 3; n <= 6; n++)
    {
      std::vector<double> A ((size_t)n * n), x ((size_t)n), b ((size_t)n, 0.0);
      for (int i = 0; i < n; i++)
        {
          x[i] = 1.0 + 0.5 * i;
          for (int j = 0; j < n; j++)
            A[i * n + j] = (i == j) ? 4.0 + i : 1.0 / (1.0 + i + 2.0 * j);
        }
      for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++) b[i] += A[i * n + j] * x[j];
      sisal_array_t Aa = mk_mat (A, n), Bb = mk_vec (b);
      const double got = func_MAIN (Aa, Bb);
      if (!(got >= 0.0 && got < 1e-12)) exact_ok = false;
      free (Aa.data); free (Bb.data);
    }
  check ("well-conditioned system with a known exact solution: residual is at "
         "machine level",
         exact_ok);

  // The -999 branch, reached via the ZERO matrix.  It is guarded by
  // `rcond = 0.0d0`, and rcond is `if anorm = 0 then 0 else ynorm4/anorm`, so
  // anorm = 0 is what actually trips it.
  //
  // A rank-1 matrix of ones was tested here too, because sgeco does not detect
  // it: the factorization hits a zero pivot, forms the multiplier 0/0 and
  // returns NaN, and `NaN = 0.0` is false so the guard never fires.  That input
  // is REMOVED rather than pinned -- an input that drives a 0/0 is a bad input,
  // not a behaviour worth asserting.  The zero matrix reaches the same branch
  // without dividing by anything (measured: U diagonal all zero, rcond exactly
  // 0, no NaN).
  {
    const int n = 4;
    std::vector<double> Z ((size_t)n * n, 0.0), b ((size_t)n, 1.0);
    sisal_array_t A = mk_mat (Z, n), B = mk_vec (b);
    const double got = func_MAIN (A, B);
    check ("zero matrix (anorm = 0) takes the rcond = 0 branch and returns -999",
           fabs (got - (-999.0)) < 1e-9);
    // and nothing in that path produced a NaN
    uint64_t bits;
    memcpy (&bits, &got, sizeof bits);
    const bool is_nan
        = ((bits >> 52) & 0x7ff) == 0x7ff && (bits & 0xfffffffffffffULL);
    check ("...with no NaN produced along the way", !is_nan);
    free (A.data); free (B.data);
  }
}
#endif

